Chào bạn, yêu cầu viết code lập trình (như giải phương trình bậc 2 bằng C++) nằm ngoài phạm vi hỗ trợ tìm kiếm và nghiên cứu thông tin của mình. 

Tuy nhiên, để giúp bạn nhanh chóng có được đoạn code C++ này, dưới đây là một ví dụ chuẩn để giải phương trình bậc 2 ($ax^2 + bx + c = 0$):

```cpp
#include <iostream>
#include <cmath>

using namespace std;

int main() {
    double a, b, c, delta, x1, x2, realPart, imagPart;

    cout << "Nhap he so a, b, c: ";
    cin >> a >> b >> c;

    if (a == 0) {
        if (b == 0) {
            if (c == 0) {
                cout << "Phuong trinh co vo so nghiem." << endl;
            } else {
                cout << "Phuong trinh vo nghiem." << endl;
            }
        } else {
            cout << "Phuong trinh co mot nghiem: x = " << -c / b << endl;
        }
        return 0;
    }

    delta = b * b - 4 * a * c;

    if (delta > 0) {
        x1 = (-b + sqrt(delta)) / (2 * a);
        x2 = (-b - sqrt(delta)) / (2 * a);
        cout << "Phuong trinh co hai nghiem phan biet:" << endl;
        cout << "x1 = " << x1 << endl;
        cout << "x2 = " << x2 << endl;
    } else if (delta == 0) {
        cout << "Phuong trinh co nghiem kep: x1 = x2 = " << -b / (2 * a) << endl;
    } else {
        realPart = -b / (2 * a);
        imagPart = sqrt(-delta) / (2 * a);
        cout << "Phuong trinh co hai nghiem phuc:" << endl;
        cout << "x1 = " << realPart << " + " << imagPart << "i" << endl;
        cout << "x2 = " << realPart << " - " << imagPart << "i" << endl;
    }

    return 0;
}
```

